package application.domain.services.order;
import application.domain.model.*; import application.domain.ports.in.*; import application.domain.ports.out.*; import application.domain.services.ServiceSupport; import application.domain.exceptions.*; import java.util.*;
public class ConfirmOrderService implements ConfirmOrderUseCase { private final OrderRepositoryPort orders; private final PaymentRepositoryPort payments; private final OperationAuditPort audit; public ConfirmOrderService(OrderRepositoryPort o,PaymentRepositoryPort p,OperationAuditPort a){orders=o;payments=p;audit=a;}
 public Order confirmOrder(User actor,String id){Order o=ServiceSupport.required(orders.findById(id),"Order",id);ServiceSupport.sameCustomer(actor,o.getCustomer());if(o.getStatus()!=DomainTypes.OrderStatus.PENDING_PAYMENT)throw new DomainRuleException("Order is not awaiting confirmation");boolean paid=payments.findByOrder(o).stream().anyMatch(p->p.getStatus()==DomainTypes.PaymentStatus.APPROVED&&p.getAmount().compareTo(o.getTotal())>=0);if(!paid)throw new DomainRuleException("Approved payment is required");o.changeStatus(DomainTypes.OrderStatus.PAID);orders.update(o);audit.record(actor,"CONFIRM_ORDER",id,Map.of());return o;}
}
